@bp.route("/grep_processes")
def grep_processes():
    import subprocess
    name = request.args.get("name", "")
    res = subprocess.run(["grep", name], input=subprocess.run(["ps", "aux"], capture_output=True).stdout, capture_output=True)
    if res.stdout is None:
        return jsonify({"error": "no stdout returned"})
    out = res.stdout.decode("utf-8")
    names = [line.split()[10] for line in out.splitlines() if len(line.split()) > 10]
    return jsonify({"success": True, "names": names})
```

